    public override Dictionary<string, object> parseWsOrder(object order, IDictionary<string, object> market = null)
    {
        //
        //     {
        //         "symbol": "PERP_BTC_USDT",
        //         "clientOrderId": 0,
        //         "orderId": 52952826,
        //         "type": "LIMIT",
        //         "side": "SELL",
        //         "quantity": 0.01,
        //         "price": 22000,
        //         "tradeId": 0,
        //         "executedPrice": 0,
        //         "executedQuantity": 0,
        //         "fee": 0,
        //         "feeAsset": "USDT",
        //         "totalExecutedQuantity": 0,
        //         "status": "NEW",
        //         "reason": '',
        //         "orderTag": "default",
        //         "totalFee": 0,
        //         "visible": 0.01,
        //         "timestamp": 1657515556798,
        //         "reduceOnly": false,
        //         "maker": false
        //     }
        // algo order
        //     {
        //         "symbol":"PERP_MATIC_USDC",
        //         "rootAlgoOrderId":123,
        //         "parentAlgoOrderId":123,
        //         "algoOrderId":123,
        //         "orderTag":"some tags",
        //         "algoType": "STOP",
        //         "clientOrderId":"client_id",
        //         "type":"LIMIT",
        //         "side":"BUY",
        //         "quantity":7029.0,
        //         "price":0.7699,
        //         "tradeId":0,
        //         "triggerTradePrice":0,
        //         "triggerTime":1234567,
        //         "triggered": false,
        //         "activated": false,
        //         "executedPrice":0.0,
        //         "executedQuantity":0.0,
        //         "fee":0.0,
        //         "feeAsset":"USDC",
        //         "totalExecutedQuantity":0.0,
        //         "averageExecutedQuantity":0.0,
        //         "avgPrice":0,
        //         "triggerPrice":0.0,
        //         "triggerPriceType":"STOP",
        //         "isActivated": false,
        //         "status":"NEW",
        //         "rootAlgoStatus": "FILLED",
        //         "algoStatus": "FILLED",
        //         "reason":"",
        //         "totalFee":0.0,
        //         "visible": 7029.0,
        //         "visibleQuantity":7029.0,
        //         "timestamp":1704679472448,
        //         "maker":false,
        //         "isMaker":false,
        //         "createdTime":1704679472448
        //     }
        //
        string? orderId = this.safeString(order, "orderId");
        string? marketId = this.safeString(order, "symbol");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        string? symbol = ((string)(marketResolved != null && marketResolved.ContainsKey("symbol") ? marketResolved["symbol"] : null));
        Int64? timestamp = this.safeInteger(order, "timestamp");
        Dictionary<string, object> fee = new Dictionary<string, object>() {
            { "cost", this.safeString(order, "totalFee") },
            { "currency", this.safeString(order, "feeAsset") },
        };
        string? priceString = this.safeString(order, "price");
        double? price = this.safeNumber(order, "price");
        double? avgPrice = this.safeNumber(order, "avgPrice");
        if (Precise.stringEq(priceString, "0") && ((avgPrice != null)))
        {
            price = avgPrice;
        }
        string? amount = this.safeString(order, "quantity");
        string? side = this.safeStringLower(order, "side");
        string? type = this.safeStringLower(order, "type");
        double? filled = this.safeNumber(order, "totalExecutedQuantity");
        string? totalExecQuantity = this.safeString(order, "totalExecutedQuantity");
        string? remaining = amount;
        if (Precise.stringGe(amount, totalExecQuantity))
        {
            remaining = Precise.stringSub(remaining, totalExecQuantity);
        }
        string? rawStatus = this.safeString(order, "status");
        string? status = this.parseOrderStatus(rawStatus);
        object trades = null;
        string? clientOrderId = this.safeString(order, "clientOrderId");
        double? triggerPrice = this.safeNumber(order, "triggerPrice");
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "symbol", symbol },
            { "id", orderId },
            { "clientOrderId", clientOrderId },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", timestamp },
            { "type", type },
            { "timeInForce", null },
            { "postOnly", null },
            { "side", side },
            { "price", price },
            { "stopPrice", triggerPrice },
            { "triggerPrice", triggerPrice },
            { "amount", amount },
            { "cost", null },
            { "average", null },
            { "filled", filled },
            { "remaining", remaining },
            { "status", status },
            { "fee", fee },
            { "trades", trades },
        });
    }

    public virtual void handleOrderUpdate(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "topic": "executionreport",
        //         "ts": 1657515556799,
        //         "data": {
        //             "symbol": "PERP_BTC_USDT",
        //             "clientOrderId": 0,
        //             "orderId": 52952826,
        //             "type": "LIMIT",
        //             "side": "SELL",
        //             "quantity": 0.01,
        //             "price": 22000,
        //             "tradeId": 0,
        //             "executedPrice": 0,
        //             "executedQuantity": 0,
        //             "fee": 0,
        //             "feeAsset": "USDT",
        //             "totalExecutedQuantity": 0,
        //             "status": "NEW",
        //             "reason": '',
        //             "orderTag": "default",
        //             "totalFee": 0,
        //             "visible": 0.01,
        //             "timestamp": 1657515556799,
        //             "maker": false
        //         }
        //     }
        //
        string? topic = this.safeString(message, "topic");
        object data = this.safeValue(message, "data");
        if (((data is IList<object>) || (data.GetType().IsGenericType && data.GetType().GetGenericTypeDefinition().IsAssignableFrom(typeof(List<>)))))
        {
            // algoexecutionreport
            for (int i = 0; i < getArrayLength(data); i++)
            {
                object order = getValue(data, i);
                string? tradeIdStr = this.safeString(data, "tradeId");
                string? tradeId = ((tradeIdStr == null)) ? null : this.omitZero(tradeIdStr);
                if ((tradeId != null))
                {
                    this.handleMyTrade(client, order);
                }
                this.handleOrder(client, order, topic);
            }
        } else
        {
            // executionreport
            string? tradeIdStr = this.safeString(data, "tradeId");
            string? tradeId = ((tradeIdStr == null)) ? null : this.omitZero(tradeIdStr);
            if ((tradeId != null))
            {
                this.handleMyTrade(client, data);
            }
            this.handleOrder(client, data, topic);
        }
    }

    public virtual void handleOrder(WebSocketClient client, object message, object topic)
    {
        Dictionary<string, object> parsed = this.parseWsOrder(message);
        string? symbol = this.safeString(parsed, "symbol");
        string? orderId = this.safeString(parsed, "id");
        if ((symbol != null))
        {
            if ((this.orders == null))
            {
                Int64? limit = this.safeInteger(this.options, "ordersLimit", 1000);
                this.orders = new ArrayCacheBySymbolById(limit);
            }
            ccxt.pro.ArrayCache cachedOrders = this.orders;
            IDictionary<string, object> orders = this.safeDict((cachedOrders as ArrayCache).hashmap, symbol, new Dictionary<string, object>() {});
            IDictionary<string, object> order = ((orderId == null)) ? null : this.safeDict(orders, orderId);
            if ((order != null))
            {
                object fee = this.safeValue(order, "fee");
                if ((fee != null))
                {
                    parsed["fee"] = fee;
                }
                List<object> fees = this.safeList(order, "fees");
                if ((fees != null))
                {
                    parsed["fees"] = fees;
                }
                parsed["trades"] = this.safeList(order, "trades", new List<object>() {});
                parsed["timestamp"] = this.safeInteger(order, "timestamp");
                parsed["datetime"] = this.safeString(order, "datetime");
            }
            cachedOrders.append(parsed);
            client.resolve(this.orders, topic);
            object messageHashSymbol = add(add(topic, ":"), symbol);
            client.resolve(this.orders, messageHashSymbol);
        }
    }

    public virtual void handleMyTrade(WebSocketClient client, object message)
    {
        //
        // {
        //     symbol: 'PERP_XRP_USDC',
        //     clientOrderId: '',
        //     orderId: 1167632251,
        //     type: 'MARKET',
        //     side: 'BUY',
        //     quantity: 20,
        //     price: 0,
        //     tradeId: '1715179456664012',
        //     executedPrice: 0.5276,
        //     executedQuantity: 20,
        //     fee: 0.006332,
        //     feeAsset: 'USDC',
        //     totalExecutedQuantity: 20,
        //     avgPrice: 0.5276,
        //     averageExecutedPrice: 0.5276,
        //     status: 'FILLED',
        //     reason: '',
        //     totalFee: 0.006332,
        //     visible: 0,
        //     visibleQuantity: 0,
        //     timestamp: 1715179456660,
        //     orderTag: 'CCXT',
        //     createdTime: 1715179456656,
        //     maker: false
        // }
        //
        string messageHash = "myTrades";
        string? marketId = this.safeString(message, "symbol");
        Dictionary<string, object> market = this.safeMarket(marketId);
        string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        Dictionary<string, object> trade = this.parseWsTrade(message, market);
        ccxt.pro.ArrayCache trades = this.myTrades;
        if ((trades == null))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            trades = new ArrayCacheBySymbolById(limit);
            this.myTrades = trades;
        }
        trades.append(trade);
        client.resolve(trades, messageHash);
        string symbolSpecificMessageHash = ((messageHash + ":") + symbol);
        client.resolve(trades, symbolSpecificMessageHash);
    }

    /**
     * @method
     * @name modetrade#watchPositions
     * @see https://orderly.network/docs/build-on-omnichain/websocket-api/private/position-push
     * @description watch all open positions
     * @param {string[]} [symbols] list of unified market symbols
     * @param {int} [since] timestamp in ms of the earliest position to fetch
     * @param {int} [limit] the maximum number of positions to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
     */
    public async override Task<List<ccxt.Position>> WatchPositions(IList<object> symbols = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        List<object> messageHashes = new List<object>() {};
        IList<object> symbolsNormalized = this.marketSymbols(symbols);
        if (((symbolsNormalized != null)) && !this.isEmpty(symbolsNormalized))
        {
            for (int i = 0; i < (symbolsNormalized?.Count ?? 0); i++)
            {
                string? symbol = ((string)symbolsNormalized[i]);
                messageHashes.Add(("positions::" + symbol));
            }
        } else
        {
            messageHashes.Add("positions");
        }
        string? wsUrl = this.safeString(getValue((this.urls != null && ((IDictionary<string, object>)this.urls).ContainsKey("api") ? ((IDictionary<string, object>)this.urls)["api"] : null), "ws"), "private");
        if ((wsUrl == null))
        {
            throw new ExchangeError ((this.id + " watchPositions() has no private websocket url")) ;
        }
        string url = ((wsUrl + "/") + this.accountId);
        var client = this.client(url);
        this.setPositionsCache(client, symbolsNormalized);
        bool fetchPositionsSnapshot = ((bool)this.handleOption("watchPositions", "fetchPositionsSnapshot", true));
        bool awaitPositionsSnapshot = ((bool)this.handleOption("watchPositions", "awaitPositionsSnapshot", true));
        if (((fetchPositionsSnapshot == true)) && ((awaitPositionsSnapshot == true)) && ((this.positions == null)))
        {
            ccxt.pro.ArrayCache snapshot = ((ccxt.pro.ArrayCache)await client.future("fetchPositionsSnapshot"));
            return ccxt.BaseExchange.ToPositionList(this.filterBySymbolsSinceLimit(snapshot, symbolsNormalized, since, limit, true));
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "event", "subscribe" },
            { "topic", "position" },
        };
        object newPositions = await this.watchPrivateMultiple(messageHashes, request, parameters);
        if (this.newUpdates)
        {
            return ccxt.BaseExchange.ToPositionList(newPositions);
        }
        return ccxt.BaseExchange.ToPositionList(this.filterBySymbolsSinceLimit(this.positions, symbolsNormalized, since, limit, true));
    }

    public virtual void setPositionsCache(WebSocketClient client, object type, IList<object> symbols = null)
    {
        bool fetchPositionsSnapshot = ((bool)this.handleOption("watchPositions", "fetchPositionsSnapshot", false));
        if ((fetchPositionsSnapshot == true))
        {
            string messageHash = "fetchPositionsSnapshot";
            if (!((client.futures != null && client.futures.ContainsKey(messageHash))))
            {
                client.future(messageHash);
                this.spawn(this.loadPositionsSnapshot, new object[] { client, messageHash});
            }
        } else
        {
            this.positions = new ArrayCacheBySymbolBySide();
        }
    }

    public async virtual Task loadPositionsSnapshot(WebSocketClient client, object messageHash)
    {
        List<object> positions = ccxt.BaseExchange.FromPositionList(await this.FetchPositions());
        this.positions = new ArrayCacheBySymbolBySide();
        ccxt.pro.ArrayCache cache = ((ccxt.pro.ArrayCache)this.positions);
        for (int i = 0; i < (positions?.Count ?? 0); i++)
        {
            IDictionary<string, object> position = ((IDictionary<string, object>)positions[i]);
            string? contracts = this.safeString(position, "contracts", "0");
            if (Precise.stringGt(contracts, "0"))
            {
                cache.append(position);
            }
        }
        // don't remove the future from the .futures cache
        if (inOp(client.futures, messageHash))
        {
            Future future = ((Future)getValue(client.futures, messageHash));
            (future as Future).resolve(cache);
            client.resolve(cache, "positions");
        }
    }

    public virtual void handlePositions(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //    {
        //        "topic":"position",
        //        "ts":1705292345255,
        //        "data":{
        //           "positions":[
        //              {
        //                     "symbol":"PERP_ETH_USDC",
        //                     "positionQty":3.1408,
        //                     "costPosition":5706.51952,
        //                     "lastSumUnitaryFunding":0.804,
        //                     "sumUnitaryFundingVersion":0,
        //                     "pendingLongQty":0.0,
        //                     "pendingShortQty":-1.0,
        //                     "settlePrice":1816.9,
        //                     "averageOpenPrice":1804.51490427,
        //                     "unsettledPnl":-2.79856,
        //                     "pnl24H":-338.90179488,
        //                     "fee24H":4.242423,
        //                     "markPrice":1816.2,
        //                     "estLiqPrice":0.0,
        //                     "version":179967,
        //                     "imrwithOrders":0.1,
        //                     "mmrwithOrders":0.05,
        //                     "mmr":0.05,
        //                     "imr":0.1,
        //                     "timestamp":1685154032762
        //              }
        //           ]
        //        }
        //    }
        //
        IDictionary<string, object> data = this.safeDict(message, "data", new Dictionary<string, object>() {});
        List<object> rawPositions = this.safeList(data, "positions", new List<object>() {});
        if ((this.positions == null))
        {
            this.positions = new ArrayCacheBySymbolBySide();
        }
        ccxt.pro.ArrayCache cache = ((ccxt.pro.ArrayCache)this.positions);
        List<object> newPositions = new List<object>() {};
        for (int i = 0; i < rawPositions.Count; i++)
        {
            IDictionary<string, object> rawPosition = this.safeDict(rawPositions, i);
            string? marketId = this.safeString(rawPosition, "symbol");
            Dictionary<string, object> market = this.safeMarket(marketId);
            Dictionary<string, object> position = this.parseWsPosition(rawPosition, market);
            newPositions.Add(position);
            cache.append(position);
            string messageHash = ("positions::" + ((market.ContainsKey("symbol") ? market["symbol"] : null)));
            client.resolve(position, messageHash);
        }
        client.resolve(newPositions, "positions");
    }

    public virtual Dictionary<string, object> parseWsPosition(object position, IDictionary<string, object> market = null)
    {
        //
        //     {
        //         "symbol":"PERP_ETH_USDC",
        //         "positionQty":3.1408,
        //         "costPosition":5706.51952,
        //         "lastSumUnitaryFunding":0.804,
        //         "sumUnitaryFundingVersion":0,
        //         "pendingLongQty":0.0,
        //         "pendingShortQty":-1.0,
        //         "settlePrice":1816.9,
        //         "averageOpenPrice":1804.51490427,
        //         "unsettledPnl":-2.79856,
        //         "pnl24H":-338.90179488,
        //         "fee24H":4.242423,
        //         "markPrice":1816.2,
        //         "estLiqPrice":0.0,
        //         "version":179967,
        //         "imrwithOrders":0.1,
        //         "mmrwithOrders":0.05,
        //         "mmr":0.05,
        //         "imr":0.1,
        //         "timestamp":1685154032762
        //     }
        //
        string? contract = this.safeString(position, "symbol");
        Dictionary<string, object> marketResolved = this.safeMarket(contract, market);
        string? size = this.safeString(position, "positionQty");
        string? side = null;
        if (Precise.stringGt(size, "0"))
        {
            side = "long";
        } else
        {
            side = "short";
        }
        string? contractSize = this.safeString(marketResolved, "contractSize");
        string? markPrice = this.safeString(position, "markPrice");
        Int64? timestamp = this.safeInteger(position, "timestamp");
        string? entryPrice = this.safeString(position, "averageOpenPrice");
        string? unrealisedPnl = this.safeString(position, "unsettledPnl");
        size = Precise.stringAbs(size);
        string? notional = Precise.stringMul(size, markPrice);
        return this.safePosition(new Dictionary<string, object>() {
            { "info", position },
            { "id", null },
            { "symbol", this.safeString(marketResolved, "symbol") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastUpdateTimestamp", null },
            { "initialMargin", null },
            { "initialMarginPercentage", null },
            { "maintenanceMargin", null },
            { "maintenanceMarginPercentage", null },
            { "entryPrice", this.parseNumber(entryPrice) },
            { "notional", this.parseNumber(notional) },
            { "leverage", null },
            { "unrealizedPnl", this.parseNumber(unrealisedPnl) },
            { "contracts", this.parseNumber(size) },
            { "contractSize", this.parseNumber(contractSize) },
            { "marginRatio", null },
            { "liquidationPrice", this.safeNumber(position, "estLiqPrice") },
            { "markPrice", this.parseNumber(markPrice) },
            { "lastPrice", null },
            { "collateral", null },
            { "marginMode", "cross" },
            { "marginType", null },
            { "side", side },
            { "percentage", null },
            { "hedged", null },
            { "stopLossPrice", null },
            { "takeProfitPrice", null },
        });
    }

    /**
     * @method
     * @name modetrade#watchBalance
     * @description watch balance and get the amount of funds available for trading or funds locked in orders
     * @see https://orderly.network/docs/build-on-omnichain/websocket-api/private/balance
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
     */
    public async override Task<ccxt.Balances> WatchBalance(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        string topic = "balance";
        string messageHash = topic;
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "event", "subscribe" },
            { "topic", topic },
        };
        Dictionary<string, object> message = this.extend(request, parameters);
        return ccxt.BaseExchange.ToBalances(await this.watchPrivate(messageHash, message));
    }

    public virtual void handleBalance(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "topic":"balance",
        //         "ts":1651836695254,
        //         "data":{
        //             "balances":{
        //                 "USDC":{
        //                     "holding":5555815.47398272,
        //                     "frozen":0,
        //                     "interest":0,
        //                     "pendingShortQty":0,
        //                     "pendingExposure":0,
        //                     "pendingLongQty":0,
        //                     "pendingLongExposure":0,
        //                     "version":894,
        //                     "staked":51370692,
        //                     "unbonding":0,
        //                     "vault":0,
        //                     "averageOpenPrice":0.00000574,
        //                     "pnl24H":0,
        //                     "fee24H":0.01914,
        //                     "markPrice":0.31885
        //                 }
        //             }
        //         }
        //     }
        //
        IDictionary<string, object> data = this.safeDict(message, "data", new Dictionary<string, object>() {});
        IDictionary<string, object> balances = this.safeDict(data, "balances", new Dictionary<string, object>() {});
        List<object> keys = new List<object>(balances.Keys);
        Int64? ts = this.safeInteger(message, "ts");
        this.balance["info"] = data;
        this.balance["timestamp"] = ts;
        this.balance["datetime"] = this.iso8601(ts);
        for (int i = 0; i < keys.Count; i++)
        {
            string? key = ((string)keys[i]);
            IDictionary<string, object> value = this.safeDict(balances, key);
            string? code = this.safeCurrencyCode(key);
            object account = this.account();
            if (((code != null)) && ((this.balance != null && code != null && this.balance.ContainsKey(code))))
            {
                account = (this.balance != null && code != null && this.balance.ContainsKey(code) ? this.balance[code] : null);
            }
            string? total = this.safeString(value, "holding");
            string? used = this.safeString(value, "frozen");
            ((IDictionary<string,object>)account)["total"] = total;
            ((IDictionary<string,object>)account)["used"] = used;
            ((IDictionary<string,object>)account)["free"] = Precise.stringSub(total, used);
            if ((code != null))
            {
                this.balance[(string)code] = account;
            }
        }
        this.balance = this.safeBalance(this.balance);
        client.resolve(this.balance, "balance");
    }

    public virtual bool? handleErrorMessage(WebSocketClient client, object message)
    {
        //
        // {"id":"1","event":"subscribe","success":false,"ts":1710780997216,"errorMsg":"Auth is needed."}
        //
        if (!((message != null && ((IDictionary<string, object>)message).ContainsKey("success"))))
        {
            return ((bool?)((object)(false)));
        }
        bool? success = this.safeBool(message, "success");
        if ((success == true))
        {
            return ((bool?)((object)(false)));
        }
        string? errorMessage = this.safeString(message, "errorMsg");
        try
        {
            if ((errorMessage != null))
            {
                string feedback = ((this.id + " ") + this.json(message));
                this.throwExactlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("exact") ? ((IDictionary<string, object>)this.exceptions)["exact"] : null), errorMessage, feedback);
            }
            return ((bool?)((object)(false)));
        } catch(Exception error)
        {
            if (error is AuthenticationError)
            {
                string messageHash = "authenticated";
                client.reject(error, messageHash);
                if ((client.subscriptions != null && client.subscriptions.ContainsKey(messageHash)))
                {
                    ((IDictionary<string,object>)client.subscriptions).Remove(messageHash);
                }
            } else
            {
                client.reject(error);
            }
            return ((bool?)((object)(true)));
        }
    }

    public override void handleMessage(WebSocketClient client, object message)
    {
        if (isEqual(this.handleErrorMessage(client, message), true))
        {
            return;
        }
        Dictionary<string, object> methods = new Dictionary<string, object>() {
            { "ping", this.handlePing },
            { "pong", this.handlePong },
            { "subscribe", this.handleSubscribe },
            { "orderbook", this.handleOrderBook },
            { "ticker", this.handleTicker },
            { "tickers", this.handleTickers },
            { "kline", this.handleOHLCV },
            { "trade", this.handleTrade },
            { "auth", this.handleAuth },
            { "executionreport", this.handleOrderUpdate },
            { "algoexecutionreport", this.handleOrderUpdate },
            { "position", this.handlePositions },
            { "balance", this.handleBalance },
            { "bbos", this.handleBidAsk },
        };
        string? eventVar = this.safeString(message, "event");
        object method = ((eventVar == null)) ? null : this.safeValue(methods, eventVar);
        if ((method != null))
        {
            DynamicInvoker.InvokeMethod(method, new object[] { client, message});
            return;
        }
        string? topic = this.safeString(message, "topic");
        if ((topic != null))
        {
            method = this.safeValue(methods, topic);
            if ((method != null))
            {
                DynamicInvoker.InvokeMethod(method, new object[] { client, message});
                return;
            }
            List<object> splitTopic = topic.Split(new [] {"@"}, StringSplitOptions.None).ToList<object>();
            int splitLength = splitTopic.Count;
            if ((splitLength == 2))
            {
                string? name = this.safeString(splitTopic, 1);
                if ((name == null))
                {
                    return;
                }
                method = this.safeValue(methods, name);
                if ((method != null))
                {
                    DynamicInvoker.InvokeMethod(method, new object[] { client, message});
                    return;
                }
                List<object> splitName = name.Split(new [] {"_"}, StringSplitOptions.None).ToList<object>();
                int splitNameLength = splitTopic.Count;
                if ((splitNameLength == 2))
                {
                    string? splitNameFirst = this.safeString(splitName, 0);
                    method = ((splitNameFirst == null)) ? null : this.safeValue(methods, splitNameFirst);
                    if ((method != null))
                    {
                        DynamicInvoker.InvokeMethod(method, new object[] { client, message});
                    }
                }
            }
        }
    }

    public override object ping(WebSocketClient client)
    {
        return new Dictionary<string, object>() {
            { "event", "ping" },
        };
    }

    public async virtual Task pong(WebSocketClient client, Dictionary<string, object> message)
    {
